import math
import statistics
import numpy as np

def task_func(input_list):
    def _rounded_stats(seq):
        if not seq:
            return (0, 0, 0)
        mean_val = statistics.mean(seq)
        median_val = statistics.median(seq)
        try:
            mode_val = statistics.mode(seq)
        except statistics.StatisticsError:
            mode_val = seq[0]
        return (
            int(round(mean_val)),
            int(round(median_val)),
            int(round(mode_val)),
        )

    values = [float(x) for x in input_list]
    if not values:
        return (0, 0, 0, 0, 0, 0)

    # Sort in ascending order based on degree value.
    sorted_values = sorted(values, key=math.degrees)

    sorted_stats = _rounded_stats(sorted_values)

    # Round degree values to the nearest integer before FFT.
    fft_input = np.rint(np.asarray(sorted_values, dtype=float))
    fft_magnitude = np.abs(np.fft.fft(fft_input)).tolist()
    fft_stats = _rounded_stats(fft_magnitude)

    return sorted_stats + fft_stats
